// Monta a pesquisa do Gemini (com busca no Google) para um trabalho do Enriquecedor.
const t = $json;
const p = t.payload || {};
const e = p.empresa || {};
const contatos = (p.contatos || []).map((c) => `${c.nome}${c.cargo ? ' (' + c.cargo + ')' : ''}${c.decisor ? ' [decisor]' : ''}`).join('; ') || 'nenhum';
const prompt = [
  'Você é o Enriquecedor da Aprimora, empresa júnior de consultoria em engenharia de produção.',
  'Pesquise na internet (site oficial, Google Maps, LinkedIn da empresa, consultas públicas de CNPJ) a empresa abaixo e devolva SOMENTE um objeto JSON, sem texto antes ou depois.',
  '',
  'Empresa: ' + (e.nome || ''),
  'Razão social: ' + (e.razao_social || 'desconhecida'),
  'CNPJ: ' + (e.cnpj || 'desconhecido'),
  'Site: ' + (e.site || 'desconhecido'),
  'Cidade/UF: ' + [e.cidade, e.uf].filter(Boolean).join('/'),
  'Segmento atual: ' + (e.segmento || 'não definido'),
  'Contatos já cadastrados: ' + contatos,
  '',
  'Formato (use "" ou [] quando não encontrar; NUNCA invente dados):',
  '{"cnpj":"","razao_social":"","nome_fantasia":"","site":"","telefone":"","email":"","endereco":"","cidade":"","uf":"",',
  ' "segmento":"","decisor":{"nome":"","cargo":"","email":"","telefone":"","linkedin":""},"emails":[],"hipoteses_dor":[],"resumo":""}',
  '',
  'Regras:',
  '- "segmento": escolha exatamente um destes ou deixe "": ' + (p.segmentos || []).join(', ') + '.',
  '- "decisor": quem decide sobre contratar consultoria (sócio, diretor, gerente industrial ou de operações). Só nomes encontrados em fonte pública.',
  '- "emails": e-mails corporativos publicados pela empresa (no máximo 3).',
  '- "hipoteses_dor": até 3 hipóteses curtas de dor ligadas aos serviços da Aprimora (' + (p.servicos || []).join(', ') + '), baseadas no que a empresa faz.',
  '- "resumo": 1 ou 2 frases sobre o que a empresa faz e o porte aparente.',
  '- Telefone com DDD. CNPJ só com números.',
].join('\n');
return {
  json: {
    trabalho: { id: t.id, negocio_id: t.negocio_id, empresa: e },
    corpo: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      tools: [{ google_search: {} }],
      generationConfig: { temperature: 0.2 },
    },
  },
};

// Lê a resposta do Gemini: extrai o JSON do texto e as fontes da busca.
const trabalho = $('Montar pesquisa').item.json.trabalho;
const c = ($json.candidates || [])[0] || {};
const texto = ((c.content || {}).parts || []).map((p) => p.text || '').join('').trim();
if (!texto) throw new Error('Gemini respondeu sem texto (' + (c.finishReason || 'sem motivo') + ')');
const inicio = texto.indexOf('{');
const fim = texto.lastIndexOf('}');
if (inicio < 0 || fim <= inicio) throw new Error('Resposta sem JSON: ' + texto.slice(0, 300));
let achado;
try {
  achado = JSON.parse(texto.slice(inicio, fim + 1));
} catch (err) {
  throw new Error('JSON inválido do Gemini: ' + err.message);
}
const fontes = (((c.groundingMetadata || {}).groundingChunks) || [])
  .map((g) => (g.web || {}).uri).filter(Boolean).slice(0, 8);
const so = (v) => String(v || '').replace(/\D/g, '');
const cnpj = so(trabalho.empresa.cnpj).length === 14 ? so(trabalho.empresa.cnpj) : so(achado.cnpj);
return { json: { trabalho, achado, fontes, cnpj: cnpj.length === 14 ? cnpj : '' } };

// Junta o que o Gemini achou com o cadastro oficial da BrasilAPI (que tem prioridade nos dados cadastrais).
const base = $('Ler resposta').item.json;
const a = base.achado || {};
const b = ($json && $json.razao_social && !$json.trabalho) ? $json : null;
const txt = (v) => (v == null ? '' : String(v).trim());
const tel = (v) => { const d = txt(v).replace(/\D/g, ''); return d.length >= 10 ? '(' + d.slice(0, 2) + ') ' + d.slice(2) : ''; };
const titulo = (s) => txt(s).toLowerCase().replace(/(^|\s)\S/g, (l) => l.toUpperCase());
const lista = (v) => (Array.isArray(v) ? v.map(txt).filter(Boolean) : []);

const dados = {
  cnpj: base.cnpj || '',
  razao_social: txt(b ? b.razao_social : a.razao_social),
  nome_fantasia: txt(b ? b.nome_fantasia : a.nome_fantasia) || txt(a.nome_fantasia),
  telefone: (b && tel(b.ddd_telefone_1)) || txt(a.telefone),
  email: txt(b && b.email ? String(b.email).toLowerCase() : a.email),
  site: txt(a.site),
  endereco: b ? [titulo(b.descricao_tipo_de_logradouro) + ' ' + titulo(b.logradouro), txt(b.numero), titulo(b.bairro)].map((s) => s.trim()).filter(Boolean).join(', ') : txt(a.endereco),
  cidade: b ? titulo(b.municipio) : txt(a.cidade),
  uf: txt(b ? b.uf : a.uf).toUpperCase().slice(0, 2),
  cnae: b && b.cnae_fiscal ? b.cnae_fiscal + ' · ' + txt(b.cnae_fiscal_descricao) : '',
  porte: b ? txt(b.porte) : '',
  situacao: b ? txt(b.descricao_situacao_cadastral) : '',
};

const d = a.decisor || {};
let decisor = { nome: txt(d.nome), cargo: txt(d.cargo), email: txt(d.email), telefone: txt(d.telefone), linkedin: txt(d.linkedin) };
// Sem decisor na busca: o primeiro sócio-administrador do quadro societário
if (!decisor.nome && b && Array.isArray(b.qsa) && b.qsa.length) {
  const s = b.qsa.find((q) => /administrador/i.test(q.qualificacao_socio || '')) || b.qsa[0];
  if (s && s.nome_socio) decisor = { nome: titulo(s.nome_socio), cargo: txt(s.qualificacao_socio), email: '', telefone: '', linkedin: '' };
}

const fontes = [...new Set([...(base.fontes || []), ...(b ? ['https://brasilapi.com.br/api/cnpj/v1/' + base.cnpj] : [])])];
return {
  json: {
    trabalho_id: base.trabalho.id,
    resultado: {
      dados_publicos: dados,
      segmento: txt(a.segmento),
      decisor,
      emails: [...new Set(lista(a.emails).map((e) => e.toLowerCase()))].slice(0, 3),
      hipoteses_dor: lista(a.hipoteses_dor).slice(0, 3),
      resumo: txt(a.resumo),
      fontes,
    },
  },
};
